import itertools, bisect
def slow(ps):
    best = 0
    for k in range(len(ps) + 1):
        for c in itertools.combinations(ps, k):
            s = sorted(c)
            if all(s[i][1] < s[i + 1][0] for i in range(len(s) - 1)): best = max(best, sum(p for _, _, p in c))
    return best
def fast(ps):
    ps = sorted(ps, key=lambda t: t[1]); ends = [p[1] for p in ps]; best = [0]
    for i, (a, b, p) in enumerate(ps):
        k = bisect.bisect_left(ends, a)          # projects ending strictly before day a
        best.append(max(best[-1], best[k] + p))
    return best[-1]
